async def read_root(my_header: str = Header()):
    return {"my_header": my_header}

client = TestClient(app)

def test_underscore_header_with_convert_underscores_true():
    # Default convert_underscores=True
    # Should NOT accept 'my_header'
    response = client.get("/", headers={"my_header": "value"})
    print(f"Response with my_header: {response.json()}")
    assert response.status_code == 422 # Expecting validation error because my-header is missing

def test_hyphen_header_with_convert_underscores_true():
    # Default convert_underscores=True
    # Should accept 'my-header'
    response = client.get("/", headers={"my-header": "value"})
    print(f"Response with my-header: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"my_header": "value"}

